/**
 * Retrieves a local image resource dynamically by name.
 * @param {string} group - "pests" or "weeds" (or "weed")
 * @param {string} category - Crop/Plant type
 * @param {string} name - Name of the pest/weed
 * @returns {number} The require ID (or null)
 */
export const getLocalImage = (group, category, name) => {
    if (!name) return null;
    let searchName = name.toLowerCase().trim();
    let searchCategory = category ? category.toLowerCase().trim() : "";
    let searchGroup = group ? group.toLowerCase().trim() : "";

    // Normalize group name
    if (searchGroup === "weed") searchGroup = "weeds";

    // Normalize Category Names (Directory Mismatches)
    if (searchCategory === "black gram and green gram") searchCategory = "balck and green gram";
    if (searchCategory === "black gram") searchCategory = "black gram"; // Explicit check
    
    // Resolve Aliases
    if (ALIASES[searchName]) searchName = ALIASES[searchName];

    // Select Repository
    const repo = searchGroup === "pests" ? PEST_IMAGES : WEED_IMAGES;
    if (!repo) return null;

    // 1. Precise Lookup
    if (searchCategory && repo[searchCategory] && repo[searchCategory][searchName]) {
        return repo[searchCategory][searchName];
    }

    // 2. Global Fallback (Search everywhere if precise match fails)
    for (const cat in repo) {
        if (repo[cat][searchName]) {
            return repo[cat][searchName];
        }
    }
    
    return null;
};

export const getCropImage = (name) => {
    if (!name) return null;
    const key = String(name).toLowerCase().trim();
    return CROP_IMAGES[key] || null;
};

/**
 * Debug function to print all available images and their "virtual" paths.
 * Since require() returns a number, we print the keys which represent the path structure.
 */
export const debugPrintAllPaths = () => {
    console.log("=== PEST IMAGES ===");
    Object.keys(PEST_IMAGES).forEach(category => {
        Object.keys(PEST_IMAGES[category]).forEach(name => {
            console.log(`images/pests/${category}/${name}.jpg`);
        });
    });

    console.log("\n=== WEED IMAGES ===");
    Object.keys(WEED_IMAGES).forEach(category => {
        Object.keys(WEED_IMAGES[category]).forEach(name => {
            console.log(`images/weed/${category}/${name}.jpg`);
        });
    });
};
